<template>
    <div class="mapa-votacion-container">
        <!-- Panel lateral izquierdo con candidatos -->
        <div class="panel-candidatos">
            <h2 class="titulo-votacion">VOTACIÓN 2022</h2>
            
            <!-- Spinner para candidatos -->
            <div v-if="loadingCandidatos" class="loading-spinner">
                <div class="spinner"></div>
                <p>Cargando candidatos...</p>
            </div>
            
            <div v-else class="candidatos-list">
                <div 
                    v-for="(candidato, index) in candidatosOrdenados" 
                    :key="index"
                    class="candidato-card"
                    @click="verDetalleCandidato(candidato)"
                >
                    <div class="candidato-avatar" :style="{ borderColor: candidato.color }">
                        <img :src="`/images/${candidato.imagen}`" :alt="candidato.nombre" />
                    </div>
                    <div class="candidato-info">
                        <h3 class="candidato-nombre">{{ candidato.nombre }}</h3>
                        <p class="candidato-votos">{{ formatVotos(candidato.total_votos) }} VOTOS</p>
                    </div>
                </div>
            </div>
        </div>

        <!-- Contenedor del mapa -->
        <div class="svg-container">
            <!-- Spinner para el mapa -->
            <div v-if="loadingMapa" class="loading-spinner">
                <div class="spinner"></div>
                <p>Aplicando colores al mapa...</p>
            </div>
            
